<div class="pagehead"><h1>جستجوی کتابخانه</h1><form><input name="q" value="<?=e($q)?>" autofocus placeholder="جستجو..."><label><input type="checkbox" name="types[]" value="books" checked> کتاب‌ها</label><label><input type="checkbox" name="types[]" value="authors" checked> مؤلفین</label><label><input type="checkbox" name="types[]" value="categories" checked> علوم</label><button>جستجو</button></form></div><?php if($q===''):?><div class="empty">نام کتاب، مؤلف یا علم را جستجو کنید.</div><?php endif;?><section><h2>کتاب‌ها (<?=count($books)?>)</h2><div class="table"><?php foreach($books as $b):?><a class="tr" href="/book?id=<?=$b['id']?>"><span><?=e($b['title'])?></span><span><?=e($b['author']??'')?></span><span><?=number_format($b['views'])?></span></a><?php endforeach;?></div></section><section><h2>مؤلفین (<?=count($authors)?>)</h2><div class="author-grid"><?php foreach($authors as $a):?><a href="/author?id=<?=$a['id']?>"><strong><?=e($a['name'])?></strong></a><?php endforeach;?></div></section><section><h2>علوم (<?=count($cats)?>)</h2><div class="science-list"><?php foreach($cats as $c):?><a href="/category?id=<?=$c['id']?>"><span><?=e($c['name'])?></span></a><?php endforeach;?></div></section>
